contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a, uint b) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(address(this).balance >= a + b);
        uint bal0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint eth0 = address(c).balance;
        c.Deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: b}(); if (__ESBMC_reverted()) return;
        assert(
            c.balances(address(this)) == bal0 + a + b &&
            address(c).balance == eth0 + a + b
        );
    }
    receive() external payable {}
}

